{
  "technical_and_design_decisions": [
    "Use the existing Spring XD 1.3.x codebase with Java 8 and Spring Framework 4.x as the baseline.",
    "Use Maven as the primary build system; add Gradle support only for the custom-module upload target (U6).",
    "Model the explicit partition count as a typed configuration property on the relevant source/sink module options, validated at module deployment time (U2).",
    "Implement dynamic partition subscription by hooking into the Kafka 0.8.2/0.9 ConsumerRebalanceListener API so partitions discovered after startup are assigned without restart (U3).",
    "Implement HDFS syncable writes using the Hadoop FileSystem hsync()/hflush() API and expose it as an opt-in boolean option (U4).",
    "Implement the no-tmp-suffix behavior as an opt-in boolean on the HDFS sink that skips the inUseSuffix and final rename, writing straight to the target path (U5).",
    "Ship the Maven upload target as a separate Maven Mojo/artifact; ship the Gradle upload target as a standalone Gradle task that calls the same REST endpoint used by the CLI (U6).",
    "Adopt semantic versioning (MAJOR.MINOR.PATCH, with optional -QUALIFIER) for custom module fragments and store the version inside the existing module metadata descriptor (U7).",
    "Diagnose U1 as a missing/incorrect ROLE_CREATE permission check in the admin_ui job-creation controller and fix it there while leaving the shell path unchanged.",
    "Treat U8 as a certification effort: install PHD 3.0, run the existing compatibility suite, and patch any environment/dependency incompatibilities without changing core XD APIs.",
    "Perform all design, implementation, and verification as a single senior developer; tasks are executed sequentially to avoid hidden coordination overhead."
  ],
  "assumptions": [
    "The Spring XD source tree, build scripts, and CI infrastructure are already available and the developer is familiar with them after a brief ramp-up.",
    "Kafka 0.8.2/0.9, HDFS (Hadoop 2.7+), and a PHD 3.0 test environment are available on the network.",
    "Bug U1 is a missing role/permission check in the admin_ui job-creation controller (consistent with the shell path working and no log output).",
    "The custom module repository layer (file-based or DB-backed) can be extended to store and retrieve a version field without a schema migration breaking existing data.",
    "Backward compatibility with already-deployed custom modules is not required unless explicitly noted; new version metadata is additive.",
    "The Maven plugin for U6 is a thin wrapper around the existing admin REST upload endpoint; no new authentication mechanism is required.",
    "The Gradle upload target for U6 can rely on Gradle's built-in task model and HTTP capabilities without third-party plugins beyond standard ones.",
    "PHD 3.0 certification is compatibility-focused: no functional regressions, dependencies upgrade to PHD-shipped versions, and the existing test suite is reused.",
    "Documentation is limited to incremental updates of the existing reference and module-configuration pages; no new guides or tutorials are required.",
    "No localization, performance benchmarking beyond smoke checks, or end-user UX work outside the admin_ui bug fix is in scope.",
    "Effort figures are most-likely work-hours of a single senior Java/Spring developer; no project management, requirements analysis, or operations work is included."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Project ramp-up and test environment preparation",
      "activity_description": "Clone the Spring XD repository, build it locally, run the existing test suite, and stand up local Kafka/HDFS/admin-ui instances needed by downstream tasks."
    },
    {
      "activity_id": "A2",
      "activity_name": "U1 - Reproduce and root-cause the job creation bug",
      "activity_description": "Reproduce the ROLE_CREATE/ROLE_ADMIN job creation failure from admin_ui while the shell path succeeds; trace the request through the UI to the controller and identify the missing permission/role check."
    },
    {
      "activity_id": "A3",
      "activity_name": "U1 - Implement role-aware job creation fix",
      "activity_description": "Add the missing authorization/permission check in the admin_ui job creation controller (or its security configuration) so that ROLE_CREATE and ROLE_ADMIN are honored consistently with the shell."
    },
    {
      "activity_id": "A4",
      "activity_name": "U1 - Test the role-based job creation fix",
      "activity_description": "Add unit and integration tests covering job creation with ROLE_CREATE, ROLE_ADMIN, and an unauthorized role, plus a manual smoke test of the admin_ui flow."
    },
    {
      "activity_id": "A5",
      "activity_name": "U2 - Design explicit partition count configuration",
      "activity_description": "Define a typed option on the relevant module(s) for explicit partition count, decide on validation rules and interaction with existing partitioner options, and update the module option metadata."
    },
    {
      "activity_id": "A6",
      "activity_name": "U2 - Implement explicit partition count support",
      "activity_description": "Wire the new partition count option through the module's option resolver into the message routing logic so the payload is routed to the intended consumer/module based on the configured count."
    },
    {
      "activity_id": "A7",
      "activity_name": "U2 - Test explicit partition count configuration",
      "activity_description": "Add unit tests for option parsing/validation and integration tests that verify payloads are routed to the expected partition under the new configuration."
    },
    {
      "activity_id": "A8",
      "activity_name": "U3 - Design dynamic partition subscription",
      "activity_description": "Decide how the Kafka source should react to newly discovered partitions, how to register a rebalance listener, and how to surface the new partitions to downstream consumers without restart."
    },
    {
      "activity_id": "A9",
      "activity_name": "U3 - Implement dynamic partition subscription in Kafka source",
      "activity_description": "Hook into Kafka's ConsumerRebalanceListener (onPartitionsAssigned/onPartitionsRevoked) and implement the runtime logic to subscribe to dynamically appearing partitions and gracefully drop revoked ones."
    },
    {
      "activity_id": "A10",
      "activity_name": "U3 - Test dynamic partition subscription",
      "activity_description": "Add unit tests with a mocked consumer covering partition add/remove events and an integration test that expands a topic's partition count at runtime and asserts that messages from the new partitions are consumed."
    },
    {
      "activity_id": "A11",
      "activity_name": "U4 - Implement HDFS syncable writes option",
      "activity_description": "Add an opt-in boolean option to the HDFS sink; when enabled, switch the file output stream to use hsync()/hflush() at appropriate points to provide better durability in case of sink/container failure."
    },
    {
      "activity_id": "A12",
      "activity_name": "U4 - Test HDFS syncable writes",
      "activity_description": "Add unit tests for the new code path and an integration test that writes a payload, kills the sink mid-write, and verifies that already-acknowledged records are durably visible (no data loss for the records marked synced)."
    },
    {
      "activity_id": "A13",
      "activity_name": "U5 - Implement direct-filename HDFS writes",
      "activity_description": "Add an opt-in boolean option to the HDFS sink that skips the inUseSuffix (.tmp) and final rename, writing directly to the configured target path; adjust close/cleanup logic accordingly."
    },
    {
      "activity_id": "A14",
      "activity_name": "U5 - Test direct-filename HDFS writes",
      "activity_description": "Add unit tests for the new option and an integration test that verifies the final file appears at the configured path with the expected name and contents, including the failure-then-recovery scenario described in U5."
    },
    {
      "activity_id": "A15",
      "activity_name": "U6 - Design Maven/Gradle upload target structure",
      "activity_description": "Decide on the artifact layout for the Maven Mojo and the Gradle task, the configuration parameters (admin URL, credentials, module coordinates), and how they delegate to the existing upload REST endpoint."
    },
    {
      "activity_id": "A16",
      "activity_name": "U6 - Implement Maven upload target",
      "activity_description": "Implement a Maven Mojo (with parameters and lifecycle binding) that packages the custom module artifact and uploads it to the Spring XD admin via the existing REST upload API."
    },
    {
      "activity_id": "A17",
      "activity_name": "U6 - Implement Gradle upload target",
      "activity_description": "Implement a Gradle task (with equivalent parameters) that uploads the custom module artifact to the Spring XD admin via the same REST upload API."
    },
    {
      "activity_id": "A18",
      "activity_name": "U6 - Test Maven/Gradle upload integration",
      "activity_description": "Add integration tests that invoke the Maven Mojo and the Gradle task against a running admin instance and assert the custom module is registered and discoverable afterwards."
    },
    {
      "activity_id": "A19",
      "activity_name": "U7 - Design custom module versioning",
      "activity_description": "Define the versioning scheme (semantic MAJOR.MINOR.PATCH), extend the module metadata descriptor to carry the version, and design how install/upgrade flows resolve and select versions."
    },
    {
      "activity_id": "A20",
      "activity_name": "U7 - Implement module versioning end-to-end",
      "activity_description": "Update the module metadata model, persistence, admin REST API, and the shell/admin-ui install/upgrade commands to support listing, installing, and upgrading specific module versions, including seamless in-place upgrades."
    },
    {
      "activity_id": "A21",
      "activity_name": "U7 - Test module versioning",
      "activity_description": "Add unit tests for version parsing/comparison and integration tests for installing a module, deploying a stream, upgrading the module to a newer version, and rolling back if needed."
    },
    {
      "activity_id": "A22",
      "activity_name": "U8 - Stand up PHD 3.0 and run certification tests",
      "activity_description": "Install PHD 3.0 (Hadoop/Yarn components used by Spring XD), deploy Spring XD against it, and execute the existing compatibility test suite, recording any failures or warnings."
    },
    {
      "activity_id": "A23",
      "activity_name": "U8 - Fix PHD 3.0 compatibility issues",
      "activity_description": "Address the failures and warnings surfaced during PHD 3.0 certification: update dependency versions, adjust configuration defaults, and patch any incompatibilities so XD runs cleanly on the PHD 3.0 bits."
    },
    {
      "activity_id": "A24",
      "activity_name": "Cross-feature integration testing",
      "activity_description": "Run an end-to-end test pass that exercises the fixed job creation flow together with the new partition, HDFS, upload, and versioning features against Kafka, HDFS, and PHD 3.0 to catch regressions."
    },
    {
      "activity_id": "A25",
      "activity_name": "Documentation updates",
      "activity_description": "Update the Spring XD reference documentation: new module options (partition count, HDFS syncable/direct writes, module versioning), the Maven/Gradle upload target usage, and a note on PHD 3.0 certification."
    },
    {
      "activity_id": "A26",
      "activity_name": "Code review, refactoring, and release preparation",
      "activity_description": "Self-review and refactor across all user stories, update release notes, and prepare the increment for handoff/merge, including final build and CI green."
    }
  ],
  "reported_total": {
    "most_likely_effort": 198
  }
}
